		Mtx concat;
		PSMTXConcat(r30, unk80050, concat);
		DCInvalidateRange(unk800A4, unk800AC * (unk800AC * 4));
		GXLoadPosMtxImm(concat, GX_PNMTX0);
		GXLoadNrmMtxImm(r30, GX_PNMTX0);
