void TSilhouette::load(JSUMemoryInputStream& stream)
{
	JDrama::TViewObj::load(stream);
	unk12               = (GXColor) { 0, 0x27, 0x77, 0xff };
	unk16               = (GXColor) { 0xff, 0xff, 0xff, 0xff };
	unk1C               = 100.0f;
	unk20               = 0.9f;
