	unk0->getModelData()->getVertexData().setVtxPosArray(unk4);
	unk0->getVertexBuffer()->setVtxPosArrayPointer(0, unk4);
	unk0->getVertexBuffer()->setVtxPosArrayPointer(1, unk4);
	unk0->getVertexBuffer()->setCurrentVtxPos(unk4);





























