// fabricated
struct Plane {
	f32 nx;
	f32 ny;
	f32 nz;
	f32 offset; // from origin

	// fabricated
	f32 sdf(Vec* local)
	{
		return local->x * nx + local->y * ny + local->z * nz + offset;
	}

	// fabricated
	void set(Vec* normal, Vec* point)
	{
		nx = normal->x;
		ny = normal->y;
		nz = normal->z;
		// project any point on a plane onto it's normal and you get the
		// distance from the origin
		offset = -(normal->x * point->x + normal->y * point->y
		           + normal->z * point->z);
	}

	// fabricated
	void set(Vec* p1, Vec* p2, Vec* p3)
	{
		Vec v1;
		Vec v2;
		Vec normal;

		VECSubtract(p1, p3, &v1);
		VECSubtract(p2, p3, &v2);
		VECCrossProduct(&v1, &v2, &normal);
		MsVECNormalize(&normal, &normal);

		nx = normal.x;
		ny = normal.y;
		nz = normal.z;
		// project any point on a plane onto it's normal and you get the
		// distance from the origin
		offset = -(normal.x * p3->x + normal.y * p3->y + normal.z * p3->z);
	}
};

Plane sViewPlane[6];

static void SetViewFrustumClipCheck(f32 top, f32 bottom, f32 left, f32 right,
                                    f32 near, f32 far)
{
	f32 farLeft;
	f32 farRight;
	f32 farBottom;
	f32 ratio = far / near;
	farLeft   = left * ratio;
	farRight  = right * ratio;
	farBottom = bottom * ratio;

	Vec corner[8];

	corner[0].x = left;
	corner[0].y = top;
	corner[0].z = -near;

	corner[1].x = farLeft;
	corner[1].y = top * ratio;
	corner[1].z = -far;

	corner[2].x = right;
	corner[2].y = top;
	corner[2].z = -near;

	corner[3].x = farRight;
	corner[3].y = top * ratio;
	corner[3].z = -far;

	corner[4].x = left;
	corner[4].y = bottom;
	corner[4].z = -near;

	corner[5].x = farLeft;
	corner[5].y = farBottom;
	corner[5].z = -far;

	corner[6].x = right;
	corner[6].y = bottom;
	corner[6].z = -near;

	corner[7].x = farRight;
	corner[7].y = farBottom;
	corner[7].z = -far;

	Vec v1;
	Vec v2;
	Vec normal;

	VECSubtract(&corner[1], &corner[0], &v1);
	VECSubtract(&corner[2], &corner[0], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[0].set(&normal, &corner[0]);

	VECSubtract(&corner[6], &corner[4], &v1);
	VECSubtract(&corner[5], &corner[4], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[1].set(&normal, &corner[4]);

	VECSubtract(&corner[4], &corner[0], &v1);
	VECSubtract(&corner[1], &corner[0], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[2].set(&normal, &corner[0]);

	VECSubtract(&corner[3], &corner[2], &v1);
	VECSubtract(&corner[6], &corner[2], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[3].set(&normal, &corner[2]);

	VECSubtract(&corner[2], &corner[0], &v1);
	VECSubtract(&corner[4], &corner[0], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[4].set(&normal, &corner[0]);

	VECSubtract(&corner[3], &corner[7], &v1);
	VECSubtract(&corner[5], &corner[7], &v2);
	VECCrossProduct(&v1, &v2, &normal);
	MsVECNormalize(&normal, &normal);
	sViewPlane[5].set(&normal, &corner[7]);
}

static f32 sKeepViewClipFovy;
static f32 sKeepViewClipAspect;
static f32 sKeepViewClipNear;
static f32 sKeepViewClipFar;

void SetViewFrustumClipCheckPerspective(f32 fovy, f32 aspect, f32 clip_near,
                                        f32 clip_far)
{
	if (fovy != sKeepViewClipFovy || aspect != sKeepViewClipAspect
	    || clip_near != sKeepViewClipNear || clip_far != sKeepViewClipFar) {
		sKeepViewClipFovy   = fovy;
		sKeepViewClipAspect = aspect;
		sKeepViewClipNear   = clip_near;
		sKeepViewClipFar    = clip_far;

		//       E
		//      /|\
		//     / | \
		//    /  |  \
		//   /   |   \
		//  /____|____\
		// L     C     R
		//
		// Vertical slice of camera frustsum, E is the eye, LR is the near
		// plane. LER then is the fovy. LEC is half of it. Tan of LEC is
		// by definition LC/EC, but EC is the near plane dist, so we get
		// what we want -- LC, half the vertical span of the near plane.
		f32 tan          = tanf(fovy * (3.141593f / 180.0f / 2.0f));
		f32 vertHalfSize = clip_near * tan;
		f32 horHalfSize  = vertHalfSize * aspect;
		SetViewFrustumClipCheck(vertHalfSize, -vertHalfSize, -horHalfSize,
		                        horHalfSize, clip_near, clip_far);
	}
}

BOOL ViewFrustumClipCheck(JDrama::TGraphics* gfx, Vec* position, f32 radius)
{
	Vec local_18;
	MTXMultVec(gfx->mViewMtx, position, &local_18);

	for (int i = 0; i < 6; ++i)
		if (-radius > sViewPlane[i].sdf(&local_18))
			return false;

	return true;
}

