		((TMtxSwingRZ*)node->getCallBackUserData())->calc(J3DSys::mCurrentMtx);
	return 1;
}

void TMtxSwingRZReverseXZ::calc(MtxPtr mtx)
{
	Vec vecX;
	Vec vecY;
	calcLocalXY(mtx, &vecX, &vecY);
	if (mFlags & 1) {
		mtx[0][0] = -vecX.x;
		mtx[1][0] = -vecX.y;
		mtx[2][0] = -vecX.z;
		mtx[0][1] = -vecY.x;
		mtx[1][1] = -vecY.y;
		mtx[2][1] = -vecY.z;
	}
}

int TMtxSwingRZReverseXZCallBack(J3DNode* node, int param)
{
	if (param == 0)
		((TMtxSwingRZReverseXZ*)node->getCallBackUserData())
		    ->calc(J3DSys::mCurrentMtx);
