	position.x = mPosition.x;
	position.y = mPosition.y + y_offset;
	position.z = mPosition.z;
	object->mPosition.set(position);
	if (mMActor) {
		MtxPtr mtx = getModel()->getAnmMtx(0);
		object->mVelocity.set(mtx[0][2] * speed,
		                      mtx[1][2] * speed + vertical_speed,
