void TMapObjBase::loadHideObjInfo(JSUMemoryInputStream& stream, s32* param_2,
                                  f32* appear_speed, f32* appear_y_speed,
                                  s32* param_5)
{
	stream >> *param_2;
	f32 val;
	stream >> val;
	*appear_speed = val * 0.06f;
	stream >> val;
	if (val < 0.0f)
		val = 20.0f;
	*appear_y_speed = val;
	s32 val2;
	stream >> val2;
	if (val2 <= 0)
		val2 = 1200;
	else
		val2 *= 10;
	*param_5 = val2;
}

