void TMapObjBase::makeRootMtxRotZ(MtxPtr ptr)
{
	f32 fVar1 = sin(mRotation.z * 0.017453294f);
	f32 fVar2 = cos(mRotation.z * 0.017453294f);

	ptr[0][0] = fVar2;
	ptr[0][1] = -fVar1;
	ptr[0][2] = 0.0f;
	ptr[0][3] = mPosition.x;

	ptr[1][0] = fVar1;
	ptr[1][1] = fVar2;
	ptr[1][2] = 0.0f;
	ptr[1][3] = mPosition.y - getObjCollisionHeightOffset();

	ptr[2][0] = 0.0f;
	ptr[2][1] = 0.0f;
	ptr[2][2] = 1.0f;
	ptr[2][3] = mPosition.z;
}

void TMapObjBase::setRootMtxRotZ()
{
