	ptr[0][0] = fVar2;
	ptr[0][1] = 0.0f;
	ptr[0][2] = fVar1;
	ptr[0][3] = mPosition.x;

	ptr[1][0] = 0.0f;
	ptr[1][1] = 1.0f;
	ptr[1][2] = 0.0f;
	ptr[1][3] = mPosition.y - getObjCollisionHeightOffset();

	ptr[2][0] = -fVar1;
	ptr[2][1] = 0.0f;
