	switch (unk150) {
	case 0: {
		MtxPtr mtxP = mtx;
		mRotation.x = MsWrap(unk154 + mInitialRotation.x, 0.0f, 360.0f);
		MsMtxSetRotX(mtxP, mRotation.x);
		if (mRotation.y != 0.0f) {
			MsMtxSetRotX(mtxP, mRotation.x);
			Mtx yRot;
			MsMtxSetRotY(yRot, mRotation.y);
			MTXConcat(yRot, mtxP, mtxP);
		} else {
			MsMtxSetRotX(mtxP, mRotation.x);
