	f32 dVar13 = MsSqrtf(mPositionDelta.x * mPositionDelta.x
	                     + mPositionDelta.z * mPositionDelta.z);
	if (dVar13 < 0.001f) {
		switch (mLodAnm->getCurrentAnmKind()) {
