				unk1CC = 0;
				unk1D0 = 0.0f;

				if (!isNowMotionBlend())
					npcWaitIn();
				else if (!mInbetweenCtrl->isMotionBlending())
					mMActor->setFrameRate(unk1D0, ANM_TYPE_BCK);
			} else {
