f32 CalcJumpVelocityY(f32 height, f32 gravity)
{
	f32 velocity = 0.0f;
	if (gravity > 0.0f)
		velocity = gravity * 0.5f
		           * (MsSqrtf(height * (1.0f / gravity) * 8.0f + 1.0f) + 1.0f);
	return velocity;
}

