					EVar6 = NPC_STOP_MOTION_BLEND_OFF;
			} else {
				if (isNormalMonte()
				    || getActorType() == ACTOR_TYPE_NPC_MONTE_WC) {
					if (!checkLiveFlag(LIVE_FLAG_UNK4000000)
					    && MsRandF() < 0.5f)
						EVar7 = NPC_ANM_KIND_UNKB;
					else
						EVar6 = NPC_STOP_MOTION_BLEND_OFF;
				} else {
					if (isNormalMare()
					    || getActorType() == ACTOR_TYPE_NPC_MARE_MC) {
						if (MsRandF() < 0.5f)
							EVar7 = NPC_ANM_KIND_UNKB;
					} else {
						int actorType = getActorType();
						switch (actorType) {
						case ACTOR_TYPE_NPC_KINOPIO:
						case ACTOR_TYPE_NPC_KINOJII:
							if (!checkLiveFlag(LIVE_FLAG_UNK4000000)) {
								if (MsRandF() < 0.5f)
									EVar7 = NPC_ANM_KIND_UNKB;
							}
							break;
						}
					}
				}
			}
		}

		requestNpcAnm_(EVar7, EVar6);
	}

	resetToTurn_();
}

bool TBaseNPC::npcWetting()
{
	bool result = false;

	if (checkUnk1DA(UNK1DA_FLAG_UNK2)) {
		offUnk1DA(UNK1DA_FLAG_UNK2);

		npcHappyIn(0);
		npcWetOut();
		result = true;
	} else if (mLodAnm->getCurrentAnmKind() == NPC_ANM_KIND_WASH) {
		if (isClean()) {
			npcHappyIn(0);
			npcWetOut();
			result = true;
		} else if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
			npcWetOut();
			result = true;
		}
	} else {
		if (isNormalMare() || mActorType == ACTOR_TYPE_NPC_MARE_MC) {
			switch (mLodAnm->getCurrentAnmKind()) {
			case NPC_ANM_KIND_UNK5:
			case NPC_ANM_KIND_UNKB:
			case NPC_ANM_KIND_UNK14:
				if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
					unk22C->doThing3(240, 480);
					if (unk22C->doThing2()) {
						EnumNpcAnmKind EVar12 = NPC_ANM_KIND_UNK7;
						if (MsRandF() < 0.5f)
							EVar12 = NPC_ANM_KIND_UNK1B;
						requestNpcAnm_(EVar12, NPC_STOP_MOTION_BLEND_OFF);
					}
				}
				break;

			case NPC_ANM_KIND_UNK7:
			case NPC_ANM_KIND_UNK1B:
				if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
					npcWetOut();
					result = true;
				}
				break;
			}
		} else {
			if (isMonte() && isMadNpc()
			    && mActorType != ACTOR_TYPE_NPC_MONTE_ME) {
				switch (mLodAnm->getCurrentAnmKind()) {
				case NPC_ANM_KIND_UNK5:
				case NPC_ANM_KIND_UNK14:
					if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
						if (isStateGoToMad_()) {
							npcMadIn();
						} else {
							npcWetOut();
							result = true;
						}
					}
					break;

				case NPC_ANM_KIND_UNK4:
					if (checkLiveFlag(LIVE_FLAG_UNK2000000))
						npcMadding();
					break;

				case NPC_ANM_KIND_MAD:
				case NPC_ANM_KIND_UNKB:
					if (checkLiveFlag(LIVE_FLAG_UNK2000000)) {
						if (npcMadding()) {
							npcWetOut();
							result = true;
						}
					} else {
						if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
							npcWetOut();
							result = true;
						}
					}
				}
			} else {
				if (isSunflowerReviving()) {
					if (sunflowerReviving()) {
						npcWetOut();
						result = true;
					}
				} else {
					switch (mActorType) {
					case ACTOR_TYPE_NPC_KINOPIO:
					case ACTOR_TYPE_NPC_KINOJII:
						if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
							switch (mLodAnm->getCurrentAnmKind()) {
							case NPC_ANM_KIND_UNK5:
								requestNpcAnm_(NPC_ANM_KIND_UNK7,
								               NPC_STOP_MOTION_BLEND_OFF);
								break;

							case NPC_ANM_KIND_UNKB:
								requestNpcAnm_(NPC_ANM_KIND_MAD,
								               NPC_STOP_MOTION_BLEND_ON);
								break;

							case NPC_ANM_KIND_UNK14:
								requestNpcAnm_(NPC_ANM_KIND_UNK18,
								               NPC_STOP_MOTION_BLEND_ON);
								break;

							case NPC_ANM_KIND_UNK7:
							case NPC_ANM_KIND_MAD:
							case NPC_ANM_KIND_UNK18:
								npcWetOut();
								result = true;
								break;
							}
						}
						break;

					default:
						if (mMActor->isCurAnmAlreadyEnd(ANM_TYPE_BCK)) {
							switch (mLodAnm->getCurrentAnmKind()) {
							case NPC_ANM_KIND_UNK5:
							case NPC_ANM_KIND_UNKB:
							case NPC_ANM_KIND_UNK14:
							case NPC_ANM_KIND_WASH:
								npcWetOut();
								result = true;
								break;
							}
						}
					}
				}
			}
		}
	}

	return result;
}

void TBaseNPC::npcWetOut()
{
	offLiveFlag(LIVE_FLAG_UNK2000000);
	offLiveFlag(LIVE_FLAG_UNK4000000);
	if (mSpine->getTop() == &TNerveNPCTalk::theNerve())
		requestTalkAnm_();
