// TODO: this/isDirty register swap and frame size (0x40 vs 0x58) remain.
void TMario::checkGraffito()
{
	if (mGroundPlane->isIllegalData())
		return;

	if (onYoshi())
		return;

	if (mPlayerType == PLAYER_TYPE_SHADOW_MARIO)
		return;
	if (mPlayerType == PLAYER_TYPE_MONTE_MAN)
		return;

	int isDirty = 0;
	JGeometry::TVec3<f32> pos;
	mPollutionTypeStandingOn
	    = gpPollution->getPollutionType(mPosition.x, mPosition.y, mPosition.z);

	switch (mPollutionTypeStandingOn) {
	case POLLUTION_TYPE_SLIP:
	case POLLUTION_TYPE_INSTAKILL:
	case POLLUTION_TYPE_SAFE: {
		pos = mPosition;
		pos.x -= 32.0f;
		pos.z -= 32.0f;
		isDirty = 1;

		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.z += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x -= 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x -= 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.z += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		pos.x += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;
		break;
	}

	case POLLUTION_TYPE_SINK:
	case POLLUTION_TYPE_FIRE:
	case POLLUTION_TYPE_GLASS_WALL:
	case POLLUTION_TYPE_UNK7: {
		pos.x = mPosition.x;
		pos.y = mFloorPosition.y;
		pos.z = mPosition.z;

		isDirty = 1;

		pos.z -= 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;

		pos.x += 32.0f;
		pos.z += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;

		pos.x -= 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;

		pos.x -= 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;

		pos.z += 32.0f;
		pos.x += 32.0f;
		if (!gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 0;

		break;
	}

	case POLLUTION_TYPE_ELECTRIC: {
		pos.x = mPosition.x;
		pos.y = mFloorPosition.y;
		pos.z = mPosition.z;
		if (gpPollution->isPolluted(pos.x, pos.y, pos.z))
			isDirty = 1;
		else
			isDirty = 0;
		break;
	}

	case POLLUTION_TYPE_UNK8:
	case POLLUTION_TYPE_UNK10:
		isDirty = 0;
		break;
	}

	if (onYoshi() && isDirty == 1)
		getOffYoshi(true);

	switch (mPollutionTypeStandingOn) {
	case POLLUTION_TYPE_ELECTRIC:
		if (isDirty == 1)
			checkGraffitoElec();
		break;
	case POLLUTION_TYPE_FIRE:
	case POLLUTION_TYPE_UNK7:
		if (isDirty == 1)
			checkGraffitoFire();
		break;
	case POLLUTION_TYPE_SLIP:
		if (isDirty == 1)
			checkGraffitoSlip();
		break;
	case POLLUTION_TYPE_GLASS_WALL:
		if (isDirty == 1) {
			mPosition.x = mPrevPosition.x;
			mPosition.z = mPrevPosition.z;
		}
		break;

	case POLLUTION_TYPE_SINK:
	case POLLUTION_TYPE_INSTAKILL:
	case POLLUTION_TYPE_SAFE:
	case 8:
		break;
	}

	if (isDirty == 1)
		onFlag(MARIO_FLAG_DIRTY);
	else
		offFlag(MARIO_FLAG_DIRTY);

	if (isTouchGround4cm()) {
		if (isDirty == 1)
			SMS_EmitSinkInPollutionEffect(mPosition, mGroundPlane->getNormal(),
			                              false);

		if (mFootPrintTimer <= 0)
			return;
		mFootPrintTimer -= 1;
		if (mFootPrintTimer <= mDeParams.mFootPrintTimerMax.get() / 2)
			return;

		if (!mGroundPlane->isLegal())
			return;

		if (checkFlag(MARIO_FLAG_IN_ANY_WATER))
			return;

		emitDirtyFootPrint();
	}
}

