	if (fly) {
		changePlayerStatus(0x89C, 0, 0);
		mYoshi->getOff(true);
	} else {
		changePlayerStatus(MARIO_STATUS_BACK_JUMP, 0, 0);
		mVel.y = mJumpParams.mGetOffYoshiY.get();
		mYoshi->getOff(false);
