	// TODO: recover the vector inline that preserves y/z for cached updates.
	// Frame-only mismatch: subtraction temporary and inlined riding matrix.
	unk160.x += offset.x;
	f32 y;
	unk160.y += (y = offset.y);
	f32 z;
	unk160.z += (z = offset.z);
	mPrevPosition.x += offset.x;
	mPrevPosition.y += y;
	mPrevPosition.z += z;
	mWireStartPos.x += offset.x;
	mWireStartPos.y += y;
	mWireStartPos.z += z;
	mWireEndPos.x += offset.x;
	mWireEndPos.y += y;
	mWireEndPos.z += z;
	unk2A8.x += offset.x;
	unk2A8.y += y;
	unk2A8.z += z;
	unk2BC += y;
	mHeadMtx[0][3] += offset.x;
	mHeadMtx[1][3] += y;
	mHeadMtx[2][3] += z;
	unk1F0[0][3] += offset.x;
	unk1F0[1][3] += y;
	unk1F0[2][3] += z;
	unk220[0][3] += offset.x;
	unk220[1][3] += y;
	unk220[2][3] += z;
	unk318[0][3] += offset.x;
	unk318[1][3] += y;
