		mPosition.z      = v->z;
		mGroundPlane     = ground;
		mFloorPosition.y = floorY;
		return 0;
	}

	if (fabsf(mPosition.y - floorY) > 100000.0f) {
		mPosition = mPrevPosition;
	} else {
