	f32 floorY;

	JGeometry::TVec3<f32> pos;
	pos.x = mHolder->mPosition.x;
	pos.y = mPosition.y;
	pos.z = mHolder->mPosition.z;

	TBGCheckData* wall1 = checkWallPlane(&pos, 60.0f, 43.0f);
	TBGCheckData* wall2 = checkWallPlane(&pos, 30.0f, 24.0f);

