void TMario::playerRefrection(int param_1)
{
	if (mWallPlane != nullptr) {
		s16 ang = matan(mWallPlane->getNormal().z, mWallPlane->getNormal().x);
		mFaceAngle.y = ang - (s16)(mFaceAngle.y - ang);
	}
	if (param_1 != 0) {
		setPlayerVelocity(-mForwardVel);
	} else {
