	if (groundCode == 1)
		unkBC = mVel.y;

	if (mRoofPlane != nullptr && !mRoofPlane->isMarioThrough()) {
		if (160.0f + pos.y > mFloorPosition.x) {
			mPosition.y = mFloorPosition.x - 160.0f;

			if (mRoofPlane->getActor() != nullptr)
				((THitActor*)mRoofPlane->getActor())
				    ->receiveMessage(this, HIT_MESSAGE_PUSH_UP);

			setPlayerVelocity(0.0f);

			if (mVel.y >= 0.0f) {
				mVel.y = 0.0f;
				if (checkFlag(MARIO_FLAG_VISIBLE))
					onFlag(MARIO_FLAG_UNK200);

				if ((param_2 & 0x2) && canHang(this) && mRoofPlane->isFence())
					roofCode = 4;
				else
					roofCode = 0;
			}
		}
	}

	mWallPlane = nullptr;

	BOOL wall1Passable = false;
	BOOL wall2Passable = false;

	if (wall1 == nullptr) {
		wall1Passable = true;
	} else if (wall1->isMarioThrough()) {
		wall1Passable = true;
	}

	if (wall2 == nullptr) {
		wall2Passable = true;
	} else if (wall2->isMarioThrough()) {
		wall2Passable = true;
	}

	if ((param_2 & 0x1) && wall1Passable == 1 && wall2Passable == 0
	    && canHang(this) == 1) {
		mWallPlane = wall2;
		if (hangonCheck(wall2, target, pos))
			wallCode = 3;
		else
			wallCode = 0;
	} else if (wall1Passable == 0 || wall2Passable == 0) {
		mWallPlane                          = wall1 != nullptr ? wall1 : wall2;
		const JGeometry::TVec3<f32>& normal = mWallPlane->getNormal();
		s16 diff   = matan(normal.z, normal.x) - (mFaceAngle.y + 0x8000);
		s16 maxAng = mJumpParams.mClashAngle.get();
		if (-maxAng < diff && diff < maxAng)
			wallCode = 2;
	}

	if (groundCode != 7)
		return groundCode;

	if (roofCode != 7)
		return roofCode;

	if (wallCode != 7)
		return wallCode;

	return 0;
}

BOOL TMario::isFallCancel()
{
	if (!(unk78 & 0x100 ? true : false))
		return false;

	if (mStatus & 0x21000)
		return false;

	if (!(mInput & 0x80) && mVel.y > 20.0f)
		return true;

	return false;
}

void TMario::fallProcess()
{
	if (mStatus == MARIO_STATUS_DIVE) {
		f32 gravity = mDivingParams.mGravity.get();
		mVel.y -= gravity;
		if (mVel.y < -75.0f)
			mVel.y = -75.0f;
	} else {
		if (isFallCancel()) {
			mVel.y *= 0.75f;
		} else if ((mStatus == MARIO_STATUS_LEFT_ROTATE_JUMP
		            || mStatus == MARIO_STATUS_RIGHT_ROTATE_JUMP)
		           && mVel.y < 0.0f) {
			f32 gravity = mJumpParams.mSpinJumpGravity.get();
			mVel.y -= gravity;
		} else {
			f32 gravity = mJumpParams.mGravity.get();
			mVel.y -= gravity;
		}
		if (onYoshi()) {
			mYoshi->thinkHoldOut();
		}
	}
	if (mVel.y < -75.0f)
		mVel.y = -75.0f;
}

int TMario::jumpProcess(int param_1)
{
	int result = 0;
	Vec next;
	f32 horizontalSpeed = std::sqrtf(mVel.x * mVel.x + mVel.z * mVel.z);

	if (horizontalSpeed > mJumpParams.mJumpingMax.get()) {
		mVel.x = mVel.x * (mJumpParams.mJumpingMax.get() / horizontalSpeed);
		mVel.z = mVel.z * (mJumpParams.mJumpingMax.get() / horizontalSpeed);
	}

	next.x  = getPosition().x + 0.25f * mVel.x;
	next.y  = getPosition().y + 0.25f * mVel.y;
	next.z  = getPosition().z + 0.25f * mVel.z;
	int ret = checkGroundAtJumping(next, param_1);
	if (ret != 0)
		result = ret;

	if (mVel.y >= 0.0f)
		unk104 = mPosition.y;

	fallProcess();

	if (mStatus != MARIO_STATUS_JUMP_CATCH)
		mFaceAngle.x = 0;

	mModelFaceAngle = mFaceAngle.y;
	return result;
}
